    public record PersonView(long id, String name, List<GradeView> grades, Integer terms, String contact, long version, int statementCount,
            String statementTotal, LocalDate statementDate, LocalDate retiredFrom, boolean held,
            List<HoldView> holds, List<Long> patronIds, List<String> aliases, boolean clashing) {

        public static PersonView of(Person person) {
            return of(person, false);
        }

        public static PersonView of(Person person, boolean clashing) {
            List<GradeView> grades = new ArrayList<>();
            grades.add(new GradeView(person.getGrade(), null));
            person.getGradesFrom().forEach((from, grade) -> grades.add(new GradeView(grade, from)));
            return new PersonView(person.getId(), person.getName(), grades, person.getTerms(), person.getContact(), person.getVersion(),
                    person.getStatementCount(),
                    person.getStatementTotal() == null ? null : person.getStatementTotal().toPlainString(),
                    person.getStatementDate(), person.getRetiredFrom(), person.isHeld(),
                    person.getHolds().stream().map(hold -> new HoldView(hold.getFromDate(), hold.getToDate())).toList(),
                    person.getPatronIds(), person.getAliases(), clashing);
        }
    }

    /** A hold on a person, from a date to a date (null: no end). */
    public record HoldView(LocalDate from, LocalDate to) {
    }

    /** A grade a person has, from a date (null: from the beginning of time). */
    public record GradeView(String grade, LocalDate from) {
    }
  return on.grade;
}

export interface PersonView {
  id: number;
  name: string;
  /** The person's grades by the date each is in force from, the first from the beginning of time. */
  grades: GradeView[];
  /** The person's own terms in days; null when they have none and take their grade's terms. */
  terms: number | null;
  /** The person's contact, trimmed and lower-cased; null when they have none. */
  contact: string | null;
  /** Raised on every save of the person. */
  version: number;
  /** How many statements have been taken for the person. */
  statementCount: number;
  /** The last statement's due-total with two decimals; null when it was n/a, or none was taken. */
  statementTotal: string | null;
  /** The date (yyyy-mm-dd) the last statement was taken as of; null when none was. */
  statementDate: string | null;
  /** The date (yyyy-mm-dd) the person is retired from; null when they are not retired. */
  retiredFrom: string | null;
  /** Whether the person has any hold, whatever its dates. */
  held: boolean;
  /** The person's holds in the order they were added: their unbound OPEN claims dated within one count in no live total. */
  holds: HoldView[];
  /** The ids of the other people on the sheet the person has named as their patrons. */
  patronIds: number[];
  /** The other names the person goes by; absent from a view kept before aliases were. */
  aliases?: string[];
  /** Whether the person's name or an alias is in use on another sheet of the sheet's tree; absent from a view kept before this was. */
  clashing?: boolean;
}

